// Command gcp03restore-credential sets the one-time built-in postgres
// password for the exact isolated g03r-1016 Cloud SQL instance and stores the
// same generated bytes in its run-scoped Secret Manager secret.
package main

import (
	"context"
	"flag"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/HernanEspinozaDev/espaciGo/internal/gcp03restorecredential"
)

func main() { os.Exit(run(os.Args[1:], os.Stdout, os.Stderr)) }

func run(args []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("gcp03restore-credential", flag.ContinueOnError)
	flags.SetOutput(stderr)
	apply := flags.Bool("apply", false, "perform the exact one-time g03r-1016 password setup")
	confirm := flags.String("confirm-target", "", "exact reviewed g03r-1016 confirmation")
	if err := flags.Parse(args); err != nil {
		if err == flag.ErrHelp {
			return 0
		}
		return 2
	}
	if flags.NArg() != 0 || !*apply || *confirm != gcp03restorecredential.Confirmation {
		fmt.Fprintf(stderr, "usage: gcp03restore-credential --apply --confirm-target=%s\n", gcp03restorecredential.Confirmation)
		return 2
	}

	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Minute)
	defer cancel()
	sql, secrets, err := gcp03restorecredential.NewGoogleAPIClients(ctx)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	result, err := (gcp03restorecredential.Provisioner{SQL: sql, Secrets: secrets}).Provision(ctx, *apply, *confirm)
	if err != nil {
		fmt.Fprintln(stderr, err)
		if result.Reconcile {
			fmt.Fprintln(stderr, "reconciliation_required=true")
			if versionNumber := gcp03restorecredential.SecretVersionNumber(result.SecretVersion); versionNumber != "" {
				fmt.Fprintf(stderr, "secret_version_number=%s\n", versionNumber)
			}
		}
		return 1
	}
	versionNumber := gcp03restorecredential.SecretVersionNumber(result.SecretVersion)
	fmt.Fprintf(stdout, "g03r-1016 postgres password configured; secret_version_number=%s operation_id=%s\n", versionNumber, result.Operation)
	return 0
}
